package ccxt

type Nado struct {
	*NadoCore
	Core          *NadoCore
	exchangeTyped *ExchangeTyped
}

func NewNado(userConfig map[string]any) *Nado {
	p := NewNadoCore()
	p.Init(userConfig)
	return &Nado{
		NadoCore:      p,
		Core:          p,
		exchangeTyped: NewExchangeTyped(&p.Exchange),
	}
}
func NewNadoFromCore(core *NadoCore) *Nado {
	return &Nado{
		NadoCore:      core,
		Core:          core,
		exchangeTyped: NewExchangeTyped(&core.Exchange),
	}
}

